import { createProject, FluentXmlFluentTest, xml, XmlFluentXmlTest } from '../test-utils'

const SCOPE = 'x_userprefs'
const project = createProject({ config: { scope: SCOPE } })

describe('User Preference plugin', () => {
    describe('Fluent to XML', () => {
        test('generates XML with the correct fields', async () => {
            const file = project.addFile({
                path: 'userpreference.now.ts',
                content: `import { UserPreference } from '@servicenow/sdk/core'

UserPreference({
    $id: Now.ID['pref-id'],
    name: 'my-pref',
    type: 'string',
    value: 'hello world',
    description: 'this is the description',
    system: false
})
`,
            })

            const prefId = project.registerExplicitId('sys_user_preference', 'pref-id')

            expect(await project.getDiagnostics()).toHaveLength(0)
            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            expect(output[0].content).toEqual(xml`<?xml version="1.0"?>
<record_update table="sys_user_preference">
  <sys_user_preference action="INSERT_OR_UPDATE">
    <sys_id>${prefId}</sys_id>
    <sys_scope display_value="${SCOPE}">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_user_preference_${prefId}</sys_update_name>
    <description>this is the description</description>
    <name>my-pref</name>
    <system>false</system>
    <type>string</type>
    <value>hello world</value>
  </sys_user_preference>
</record_update>`)
        })
    })

    describe('XML to Fluent', () => {
        test('basic XML', async () => {
            const project = createProject({ rootDir: __dirname })
            const output = await project.transform('./xml/sys_user_preference_d3d45fb524d243488789eb71cbbcfada.xml')

            expect(output.changedFiles).toHaveLength(1)
            expect(output.changedFiles[0].getContent()).toMatchInlineSnapshot(`
"import { UserPreference } from '@servicenow/sdk/core'

UserPreference({
    $id: Now.ID['d3d45fb524d243488789eb71cbbcfada'],
    system: false,
    name: 'my-pref',
    type: 'string',
    value: 'hello world',
    description: 'this is the description',
})
"
`)
        })
    })

    describe('Fluent => XML => Fluent', () => {
        test('file round-trips correctly', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const id = roundTripTest.addId('sys_user_preference', 'pref-id')
            roundTripTest.addExpectedXmlFileNames(`sys_user_preference_${id}.xml`)

            roundTripTest.addFluentFragment(`
import { UserPreference } from '@servicenow/sdk/core'

UserPreference({
    $id: Now.ID['pref-id'],
    name: 'my-pref',
    type: 'string',
    value: 'hello world',
    description: 'this is the description',
    system: false
})
`)

            await roundTripTest.verify()
        })
    })

    describe('XML => Fluent => XML', () => {
        test('file round-trips correctly', async () => {
            const project = createProject({ rootDir: __dirname })
            const originalFiles = ['./xml/sys_user_preference_d3d45fb524d243488789eb71cbbcfada.xml']
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
})
